sub _admit_locked {
    die "image maintenance admission requires the sealed coordinator\n"
        unless caller eq 'NativeProxyImageCoordination';
    my ($case, $census, $references, $key) = @_;
    my $images = _all_images($case, $census->{images});
    my ($candidate) = grep { $_->{snapshot}{key} eq $key } @$images;
    die "selected maintenance image is absent\n" unless defined($candidate);
    die "selected image is retained by an unresolved reference\n"
        if _referenced($references, $key);
    return {key => $key, images => $images, candidate => $candidate,
            references => $references, names => [@{$census->{images}}]};
}

sub _request {
    my ($case, $acquired, $cleanup) = @_;
    NativeProxyRuntimeRecord::_fields($acquired,
        qw(schema runtime_authorized executable lock reference created image));
    die "expected inactive acquisition receipt\n"
        unless NativeProxyRuntimeRecord::_string($acquired->{schema}) eq 'fsmgen.inactive_runtime_reference_acquisition.v1'
            && !defined($acquired->{executable});
    NativeProxyRuntimeRecord::_integer($acquired->{$_}) for qw(runtime_authorized created);
    die "invalid inactive acquisition flags\n" if $acquired->{runtime_authorized} != 0 || $acquired->{created} > 1;
    NativeProxyRuntimeRecord::_fields($acquired->{lock}, qw(path device inode));
    die "acquired lock path differs from store\n"
        unless NativeProxyRuntimeRecord::_string($acquired->{lock}{path}) eq "$case/coordination.lock";
    NativeProxyRuntimeRecord::_integer($acquired->{lock}{$_}) for qw(device inode);
    NativeProxyRuntimeRecord::_fields($acquired->{reference}, qw(record global private));
    my $record = $acquired->{reference}{record};
    my $raw = NativeProxyRuntimeRecord::encode_runtime_record($case, $record);
    for my $kind (qw(global private)) {
        my $snapshot = $acquired->{reference}{$kind};
        _snapshot_fields($snapshot, 4096);
        my $path = $kind eq 'global' ? "$case/references/$record->{reference_key}.json"
            : "$record->{workspace}/rust-tools/image-reference.json";
        die "acquired reference path or bytes differ\n"
            unless $snapshot->{identity}{path} eq $path && $snapshot->{bytes} eq $raw;
    }
    NativeProxyRuntimeRecord::_fields($acquired->{image}, qw(key snapshots));
    NativeProxyRuntimeRecord::_digest($acquired->{image}{key});
    die "acquired image key or source set differs\n"
        unless $acquired->{image}{key} eq $record->{image_key}
            && ref($acquired->{image}{snapshots}) eq 'ARRAY' && @{$acquired->{image}{snapshots}} == 3;
    _snapshot_fields($_, 65_536) for @{$acquired->{image}{snapshots}};
    die "acquired record source identities differ from image\n"
        unless $JSON->encode($record->{selected_sources}) eq $JSON->encode(
            [map { $_->{identity} } @{$acquired->{image}{snapshots}}[0,1]]);
    NativeProxyRuntimeRecord::_fields($cleanup, qw(compiler outer stages));
    die "complete compiler, outer and inner cleanup is unproved\n"
        unless NativeProxyCleanupReceipts::cleanup_receipts_settled(@$cleanup{qw(compiler outer stages)});
}

sub _retire_locked {
    die "retirement requires the sealed coordinator\n" unless caller eq 'NativeProxyImageCoordination';
    my ($plan) = @_;
    _reference($plan->{reference}{global});
    _reference($plan->{reference}{private});
    NativeProxyPrivateWorkspace::_remove($plan->{workspace});
    die "private workspace absence is unproved\n"
        unless NativeProxyPrivateWorkspace::_absent($plan->{workspace}{workspace}{path});
}

sub _release_locked {
    die "reference release requires the sealed coordinator\n" unless caller eq 'NativeProxyImageCoordination';
    my ($plan, $current) = @_;
    _preserved($plan->{before}, $current);
    die "private workspace reappeared before release\n"
        unless NativeProxyPrivateWorkspace::_absent($plan->{workspace}{workspace}{path});
    _reference($plan->{reference}{global});
    my $global = $plan->{reference}{global}{identity}{path};
    _unlink_global($global);
    die "released global reference remains present\n" unless NativeProxyPrivateWorkspace::_absent($global);
}

sub _prepare {
    my ($state, $case, $request, $acquired, $archive_receipt, $selection, $settlement) = @_;
    $request = NativeProxyObservationAcquisition::_request($request);
    $acquired = NativeProxyObservationAcquisition::_previous($case, $request, $acquired);
    my $spec = NativeProxyObservationArchiveRecord::archive_specification($case, $request, $acquired);
    NativeProxyObservationArchiveRecord::validate_archive_receipt($case, $request, $acquired, $archive_receipt);
    NativeProxyObservationWorkRecord::validate_work_settlement($case, $request, $acquired, $selection, $settlement);
    NativeProxyObservationArchive::_limits($spec);
    @$state{qw(case request acquired archive_receipt selection settlement)} =
        ($case, $request, $acquired, _copy($archive_receipt), _copy($selection), _copy($settlement));
    my $evidence = $spec->{evidence_directory_identity};
    my $prior = NativeProxyObservationAcquisition::_prior_directory($evidence, 'release evidence');
    # There is deliberately no creation/publication route in release admission.
    my $directory = NativeProxyImageCustody::_directory("$ROOT/$spec->{archive_directory}");
    die "release archive directory differs from original custody\n"
        unless $directory->[0] == $archive_receipt->{archive_directory_identity}{device}
            && $directory->[1] == $archive_receipt->{archive_directory_identity}{inode};
    $state->{archive_state} = {spec => $spec, sources => [], directories => [
        {path => $evidence->{path}, metadata => $prior},
        {path => $spec->{archive_directory}, metadata => $directory}]};
    $state->{archive_names} = [map { "$_->{sha256}.source" } @{$spec->{files}}];
    NativeProxyObservationArchive::_members($state->{archive_state}, $state->{archive_names});
    for my $file (@{$spec->{files}}) {
        # Register actual ownership before any validation can throw.
        push @{$state->{owned}}, NativeProxyImageCustody::_source("$ROOT/$file->{path}", 0400, 65_536);
        my $source = $state->{owned}[-1];
        push @{$state->{archive_state}{sources}}, $source;
        die "release archive bytes differ from retained original\n" unless $source->{bytes} eq $file->{bytes};
        NativeProxyImageCustody::_recheck_source($source);
    }
    _archive_closure($state);
}

sub _admit_locked {
    die "release ownership admission requires the fixed coordinator\n" unless caller eq 'NativeProxyImageCoordination';
    my ($case, $before, $state) = @_;
    my $original = $state->{acquired}{observation_reference};
    my ($hold) = grep { $_->{source}{identity}{path} eq $original->{source}{identity}{path} } @{$before->{references}};
    die "original observation hold is absent or changed\n" unless defined($hold) && _same($hold, $original);
    my ($image) = grep { $_->{key} eq $original->{record}{image_key} } @{$before->{images}};
    _current_image($state, $image);
    @$state{qw(before image)} = ($before, $image);
    _archive_closure($state);
    _retain_live_sources($state);
    return $state;
}

sub _unlink_exact {
    die "exact unlink requires the release owner\n" unless caller eq __PACKAGE__;
    my ($state) = @_;
    my $path = $state->{acquired}{observation_reference}{source}{identity}{path};
    $state->{effect}{unlink_attempted} = 1;
    unlink("$ROOT/$path") == 1 or die "cannot unlink exact observation hold: $!\n";
    # Record the actual successful syscall before a later helper can fail.
    $state->{effect}{unlink_completed} = 1;
}

sub release_observation_reference {
    die "expected store, request, acquisition, archive, original selection and settlement\n" unless @_ == 6;
    my ($case, $request, $acquired, $archive, $selection, $settlement) = @_;
    my $state = {owned => [], effect => {unlink_attempted => 0, unlink_completed => 0,
        reference_absence_verified => 0, last_reference_check => undef}};
    my $receipt;
    my $ok = eval {
        _prepare($state, $case, $request, $acquired, $archive, $selection, $settlement);
        $receipt = NativeProxyImageCoordination::_transaction($case, 'release_observation_reference', $state);
        1;
    };
    my $error = $@;
    my $close_error = _close_owned($state->{owned});
    $error = $close_error if $ok && length($close_error);
    my $success = $ok && !length($close_error);
    return {schema => 'fsmgen.inactive_observation_release_attempt.v1', runtime_authorized => 0,
        executable => undef, success => $success ? 1 : 0, error => $success ? '' : $error,
        %{$state->{effect}}, release => $success ? $receipt : undef};
}

sub _sealed {
    my ($value) = @_;
    NativeProxyRuntimeRecord::_integer($value);
    die "selected work is not sealed\n" unless $value == 1;
}

sub _cleanup_settled {
    my ($cleanup) = @_;
    NativeProxyRuntimeRecord::_fields($cleanup, qw(leader_started leader_reaped group_gone));
    die "selected work cleanup is incomplete\n"
        unless NativeProxyCleanupReceipts::_settled_owner({cleanup => $cleanup});
}

sub validate_work_settlement {
    die "expected store, request, acquisition, original selection and settlement\n" unless @_ == 5;
    my ($case, $request, $acquired, $selection, $settlement) = @_;
    _validate_selection($case, $request, $acquired, $selection);
    NativeProxyRuntimeRecord::_fields($settlement, qw(schema runtime_authorized executable selection selection_sealed receipts));
    _inactive($settlement, $SETTLEMENT_SCHEMA);
    die "settlement replaces original selection\n" unless _same($settlement->{selection}, $selection);
    _sealed($settlement->{selection_sealed});
    my $receipts = $settlement->{receipts};
    _complete_order($selection->{entries}, $receipts);
    for my $index (0..$#$receipts) {
        my $receipt = $receipts->[$index];
        NativeProxyRuntimeRecord::_fields($receipt, qw(work_id ownership_token role outcome cleanup));
        _work($receipt);
        _work_match($selection->{entries}[$index], $receipt);
        die "expected completed, failed or cancelled outcome\n"
            unless NativeProxyRuntimeRecord::_string($receipt->{outcome}) =~ /\A(?:completed|failed|cancelled)\z/;
        _cleanup_settled($receipt->{cleanup});
        die "work receipt exceeds byte ceiling\n" if length($JSON->encode($receipt)) > $RECEIPT_LIMIT;
    }
    die "work settlement exceeds byte ceiling\n" if length($JSON->encode($settlement)) > $SETTLEMENT_LIMIT;
    return 1;
}

sub _admit_locked {
    die "observation admission requires the sealed coordinator\n"
        unless caller eq 'NativeProxyImageCoordination';
    my ($case, $census, $request, $previous) = @_;
    $request = _request($request);
    $previous = _previous($case, $request, $previous) if defined($previous);
    my $workspace = $request->{workspace_identity};
    my $evidence = $request->{evidence_directory_identity};
    my $reference_key = NativeProxyImageCustody::observation_reference_key(
        $evidence->{path}, $request->{observer_birth}, $request->{target_birth});
    my $destination = "$case/references/$reference_key.json";
    if (defined($previous)) {
        my ($entry) = grep { $_->{source}{identity}{path} eq $destination } @{$census->{references}};
        _prior_hold_matches($previous, $entry);
    } else {
        die "observation reference already exists\n" if -e "$ROOT/$destination" || -l "$ROOT/$destination";
        die "observation reference capacity exceeded\n" if @{$census->{references}} >= 128;
    }
    my $runtime_key = NativeProxyImageCustody::runtime_reference_key($workspace->{path});
    my @runtime = grep { $_->{record}{schema} eq 'fsmgen.test.rust_proxy_image_reference.v1'
        && $_->{record}{reference_key} eq $runtime_key } @{$census->{references}};
    die "observation runtime reference is absent\n" unless @runtime == 1;
    my $runtime = $runtime[0];
    die "runtime reference differs from prior workspace\n"
        unless $JSON->encode($runtime->{record}{workspace_identity}) eq $JSON->encode($workspace);
    my $image_key = $runtime->{record}{image_key};
    my @images = grep { $_->{key} eq $image_key } @{$census->{images}};
    die "observation image snapshot is absent\n" unless @images == 1;
    my $image = $images[0];
    my $plan = {request => $request, destination => $destination, sources => [], directories => []};
    $plan->{previous} = $previous if defined($previous);
    my $ok = eval {
        push @{$plan->{directories}}, {path => $workspace->{path}, metadata => _prior_directory($workspace, 'workspace')};
        push @{$plan->{directories}}, {path => $evidence->{path}, metadata => _prior_directory($evidence, 'evidence')};
        for my $path ("$workspace->{path}/rust-tools", "$case/images/$image_key") {
            push @{$plan->{directories}}, {path => $path, metadata => NativeProxyImageCustody::_directory("$ROOT/$path")};
        }
        $plan->{specifications} = [
            ["$workspace->{path}/rust-tool-resolution", 0700, 65_536],
            ["$workspace->{path}/rust-tools/image-reference.json", 0400, 4096],
            ["$case/references/$runtime_key.json", 0400, 4096],
            ["$case/images/$image_key/rustup.c", 0400, 65_536],
            ["$case/images/$image_key/rustup", 0500, 65_536],
        ];
        for my $spec (@{$plan->{specifications}}) {
            push @{$plan->{sources}}, NativeProxyImageCustody::_source("$ROOT/$spec->[0]", @$spec[1,2]);
        }
        my @snapshots = map { NativeProxyReferenceCensus::_snapshot($_) } @{$plan->{sources}};
        die "private/global runtime reference differs\n"
            unless $snapshots[1]{bytes} eq $snapshots[2]{bytes}
                && $JSON->encode($snapshots[2]) eq $JSON->encode($runtime->{source});
        NativeProxyRuntimeRecord::decode_runtime_record($case, $snapshots[1]{bytes});
        for my $index (0,1) {
            die "runtime reference does not bind current canonical source\n"
                unless $JSON->encode($runtime->{record}{selected_sources}[$index])
                    eq $JSON->encode($snapshots[$index+3]{identity});
            die "observation source differs from admitted image\n"
                unless $JSON->encode($snapshots[$index+3]) eq $JSON->encode($image->{snapshots}[$index]);
        }
        if (defined($previous)) {
            _prior_targets_match($previous, \@snapshots);
            push @{$plan->{specifications}}, [$destination, 0400, 4096];
            my $hold = NativeProxyImageCustody::_source("$ROOT/$destination", 0400, 4096);
            push @{$plan->{sources}}, $hold;
            _prior_hold_matches($previous, {
                record => NativeProxyObservationRecord::decode_observation_record($case, $hold->{bytes}),
                source => NativeProxyReferenceCensus::_snapshot($hold)});
            $plan->{sealed} = $hold->{metadata};
        }
        $plan->{record} = {schema => 'fsmgen.test.rust_proxy_image_observation_reference.v1',
            reference_key => $reference_key, image_key => $image_key,
            evidence_directory => $evidence->{path}, evidence_directory_identity => $evidence,
            observer_birth => $request->{observer_birth}, target_birth => $request->{target_birth},
            selected_sources => [map { +{%{$snapshots[$_]{identity}}} } (3,4)]};
        $plan->{bytes} = NativeProxyObservationRecord::encode_observation_record($case, $plan->{record});
        _source_closure($plan);
        _directory_closure($plan);
        1;
    };
    my $error = $@;
    unless ($ok) {
        _close_sources($plan->{sources});
        die $error;
    }
    return $plan;
}

sub _transaction {
    my ($case, $operation, @payload) = @_;
    die "unknown inactive transaction\n" unless defined($operation) && !ref($operation)
        && (($operation eq 'inspect' && !@payload)
            || ($operation eq 'publish_image' && @payload == 2
                && defined(&NativeProxyImagePublication::_publish_locked))
            || (($operation eq 'inspect_runtime_references' || $operation eq 'inspect_references') && !@payload
                && defined(&NativeProxyReferenceCensus::_inspect_locked))
            || ($operation eq 'acquire_runtime_reference' && @payload == 3
                && defined(&NativeProxyReferenceAcquisition::_admit_locked)
                && defined(&NativeProxyReferenceCensus::_inspect_locked)
                && defined(&NativeProxyImagePublication::_publish_locked))
            || ($operation eq 'retire_runtime_reference' && @payload == 2
                && defined(&NativeProxyRuntimeRetirement::_admit_locked)
                && defined(&NativeProxyReferenceCensus::_inspect_locked))
            || ($operation eq 'remove_unreferenced_image' && @payload == 1
                && defined(&NativeProxyImageMaintenance::_admit_locked)
                && defined(&NativeProxyReferenceCensus::_inspect_locked))
            || ($operation eq 'acquire_observation_reference' && @payload == 1
                && defined(&NativeProxyObservationAcquisition::_admit_locked)
                && defined(&NativeProxyReferenceCensus::_inspect_locked))
            || ($operation eq 'reuse_observation_reference' && @payload == 2
                && defined(&NativeProxyObservationAcquisition::_admit_locked)
                && defined(&NativeProxyReferenceCensus::_inspect_locked))
            || ($operation eq 'release_observation_reference' && @payload == 1
                && (caller eq 'NativeProxyObservationRelease')
                && defined(&NativeProxyObservationRelease::_coordinator_request)
                && defined(&NativeProxyObservationRelease::_admit_locked)
                && defined(&NativeProxyObservationRelease::_release_locked)
                && defined(&NativeProxyObservationRelease::_finish_locked)
                && defined(&NativeProxyReferenceCensus::_inspect_locked)));
    NativeProxyImageCustody::image_key(@payload) if $operation eq 'publish_image';
    NativeProxyReferenceAcquisition::_request(@payload) if $operation eq 'acquire_runtime_reference';
    NativeProxyRuntimeRetirement::_request($case, @payload) if $operation eq 'retire_runtime_reference';
    NativeProxyImageMaintenance::_request(@payload) if $operation eq 'remove_unreferenced_image';
    NativeProxyObservationAcquisition::_request(@payload) if $operation eq 'acquire_observation_reference';
    if ($operation eq 'reuse_observation_reference') {
        my $request = NativeProxyObservationAcquisition::_request($payload[0]);
        NativeProxyObservationAcquisition::_previous($case, $request, $payload[1]);
    }
    NativeProxyObservationRelease::_coordinator_request($case, @payload)
        if $operation eq 'release_observation_reference';
    NativeProxyImageCustody::_relative_path($case);
    die "only the inactive qualification namespace is admitted\n"
        unless $case =~ /\A\Q$CASE_PREFIX\Efsmgen-[A-Za-z0-9_]+\z/;
    my $base = File::Spec->catdir($ROOT, $case);
    my $root_before = NativeProxyImageCustody::_directory($base);
    my $path = "$base/coordination.lock";
    my $existing_only = $operation eq 'retire_runtime_reference' || $operation eq 'remove_unreferenced_image'
        || $operation eq 'acquire_observation_reference' || $operation eq 'reuse_observation_reference'
        || $operation eq 'release_observation_reference';
    my $purpose = $operation eq 'retire_runtime_reference' ? 'retirement'
        : $operation eq 'remove_unreferenced_image' ? 'maintenance' : 'observation';
    my $handle = $existing_only
        ? _open_existing_lock($path, $purpose)
        : _open_lock($path);
    my $result;
    my $ok = eval {
        my $before = _lock_identity($handle, $path);
        my $flags = fcntl($handle, F_GETFD, 0);
        die "cannot read permanent lock descriptor flags: $!\n" unless defined $flags;
        fcntl($handle, F_SETFD, $flags | FD_CLOEXEC)
            or die "cannot seal permanent lock descriptor inheritance: $!\n";
        _acquire($handle, $path, $before);
        die "retirement lock differs from acquired identity\n"
            if $operation eq 'retire_runtime_reference'
                && ($before->[0] != $payload[0]{lock}{device} || $before->[1] != $payload[0]{lock}{inode});
        die "observation lock differs from acquired identity\n"
            if $operation eq 'reuse_observation_reference'
                && ($before->[0] != $payload[1]{lock}{device} || $before->[1] != $payload[1]{lock}{inode});
        die "release lock differs from acquired identity\n"
            if $operation eq 'release_observation_reference'
                && ($before->[0] != $payload[0]{acquired}{lock}{device}
                    || $before->[1] != $payload[0]{acquired}{lock}{inode});
        die "store root replaced during acquisition\n"
            unless NativeProxyImageCustody::_same_metadata(
                $root_before, NativeProxyImageCustody::_directory($base), 0,1,2,4);
        _structure($base, $existing_only ? 0 : 1);
        my @directories = map { NativeProxyImageCustody::_directory("$base/$_") } qw(images references);
        my $census = _census($base);
        my $publication = $operation eq 'publish_image'
            ? NativeProxyImagePublication::_publish_locked($case, $census, @payload) : undef;
        my $references = $operation eq 'inspect_runtime_references' || $operation eq 'inspect_references'
            ? NativeProxyReferenceCensus::_inspect_locked($case, $census,
                $operation eq 'inspect_runtime_references' ? 1 : 0) : undef;
        my $acquisition;
        if ($operation eq 'acquire_runtime_reference') {
            my $before = NativeProxyReferenceCensus::_inspect_locked($case, $census);
            my $plan = NativeProxyReferenceAcquisition::_admit_locked($case, $census, $payload[0]);
            my $published = NativeProxyImagePublication::_publish_locked($case, $census, @payload[1,2]);
            my $acquired = NativeProxyReferenceAcquisition::_acquire_locked($case, $plan, $published);
            my $after = NativeProxyReferenceCensus::_inspect_locked($case, _census($base));
            $acquisition = NativeProxyReferenceAcquisition::_finish_locked(
                $case, $plan, $published, $acquired, $before, $after);
        }
        my $retirement;
        if ($operation eq 'retire_runtime_reference') {
            my $before = NativeProxyReferenceCensus::_inspect_locked($case, $census);
            my $plan = NativeProxyRuntimeRetirement::_admit_locked($case, $before, $payload[0]);
            NativeProxyRuntimeRetirement::_retire_locked($plan);
            my $current = NativeProxyReferenceCensus::_inspect_locked($case, _census($base));
            NativeProxyRuntimeRetirement::_release_locked($plan, $current);
            my $final_census = _census($base);
            die "retirement changed image namespace membership\n"
                unless join(',', @{$census->{images}}) eq join(',', @{$final_census->{images}});
            my $after = NativeProxyReferenceCensus::_inspect_locked($case, $final_census);
            $retirement = NativeProxyRuntimeRetirement::_finish_locked($case, $plan, $after);
        }
        my $maintenance;
        if ($operation eq 'remove_unreferenced_image') {
            my $references = NativeProxyReferenceCensus::_inspect_locked($case, $census);
            my $plan = NativeProxyImageMaintenance::_admit_locked($case, $census, $references, $payload[0]);
            my $current = _census($base);
            my $current_references = NativeProxyReferenceCensus::_inspect_locked($case, $current);
            NativeProxyImageMaintenance::_closure_locked($case, $plan, $current, $current_references);
            NativeProxyImageMaintenance::_remove_locked($case, $plan);
            my $after = _census($base);
            my $after_references = NativeProxyReferenceCensus::_inspect_locked($case, $after);
            $maintenance = NativeProxyImageMaintenance::_finish_locked($case, $plan, $after, $after_references);
        }
        my $release;
        if ($operation eq 'release_observation_reference') {
            my $before = NativeProxyReferenceCensus::_inspect_locked($case, $census);
            my $plan = NativeProxyObservationRelease::_admit_locked($case, $before, $payload[0]);
            my $current = NativeProxyReferenceCensus::_inspect_locked($case, _census($base));
            NativeProxyObservationRelease::_release_locked($case, $plan, $current);
            my $final_census = _census($base);
            die "observation release changed image namespace membership\n"
                unless join(',', @{$census->{images}}) eq join(',', @{$final_census->{images}});
            my $after = NativeProxyReferenceCensus::_inspect_locked($case, $final_census);
            $release = NativeProxyObservationRelease::_finish_locked($case, $plan, $after);
        }
        my $observation;
        if ($operation eq 'acquire_observation_reference' || $operation eq 'reuse_observation_reference') {
            my $before = NativeProxyReferenceCensus::_inspect_locked($case, $census);
            my $plan = NativeProxyObservationAcquisition::_admit_locked($case, $before, @payload);
            my $complete = eval {
                my $sealed = NativeProxyObservationAcquisition::_acquire_locked($plan);
                my $final_census = _census($base);
                die "observation acquisition changed image namespace membership\n"
                    unless join(',', @{$census->{images}}) eq join(',', @{$final_census->{images}});
                my $after = NativeProxyReferenceCensus::_inspect_locked($case, $final_census);
                $observation = NativeProxyObservationAcquisition::_finish_locked($case, $plan, $sealed, $before, $after);
                1;
            };
            my $error = $@;
            my $close_error = NativeProxyObservationAcquisition::_close_sources($plan->{sources});
            die $error unless $complete;
            die $close_error if length($close_error);
        }
        _structure($base, 0);
        for my $i (0, 1) {
            my $name = $i ? 'references' : 'images';
            die "store namespace directory replaced\n"
                unless NativeProxyImageCustody::_same_metadata(
                    $directories[$i], NativeProxyImageCustody::_directory("$base/$name"), 0,1,2,4);
        }
        die "store root replaced during census\n"
            unless NativeProxyImageCustody::_same_metadata(
                $root_before, NativeProxyImageCustody::_directory($base), 0,1,2,4);
        die "permanent lock replaced during census\n"
            unless NativeProxyImageCustody::_same_metadata(
                $before, _lock_identity($handle, $path), 0,1,2,3,4,7);
        my $lock = {path => "$case/coordination.lock", device => $before->[0], inode => $before->[1]};
        $result = $operation eq 'publish_image'
            ? {schema => 'fsmgen.inactive_image_publication.v1', runtime_authorized => 0,
               executable => undef, lock => $lock, %$publication}
            : $operation eq 'inspect_runtime_references'
            ? {schema => 'fsmgen.inactive_runtime_reference_census.v1', runtime_authorized => 0,
               executable => undef, lock => $lock, %$references}
            : $operation eq 'inspect_references'
            ? {schema => 'fsmgen.inactive_image_reference_census.v1', runtime_authorized => 0,
               executable => undef, lock => $lock, %$references}
            : $operation eq 'acquire_runtime_reference'
            ? {schema => 'fsmgen.inactive_runtime_reference_acquisition.v1', runtime_authorized => 0,
               executable => undef, lock => $lock, %$acquisition}
            : $operation eq 'retire_runtime_reference'
            ? {schema => 'fsmgen.inactive_runtime_retirement.v1', runtime_authorized => 0,
               executable => undef, lock => $lock, %$retirement}
            : $operation eq 'remove_unreferenced_image'
            ? {schema => 'fsmgen.inactive_image_maintenance.v1', runtime_authorized => 0,
               executable => undef, lock => $lock, %$maintenance}
            : $operation eq 'release_observation_reference'
            ? {schema => 'fsmgen.inactive_observation_release.v1', runtime_authorized => 0,
               executable => undef, lock => $lock, %$release}
            : $operation eq 'acquire_observation_reference' || $operation eq 'reuse_observation_reference'
            ? {schema => 'fsmgen.inactive_observation_acquisition.v1', runtime_authorized => 0,
               executable => undef, lock => $lock, %$observation}
            : {schema => 'fsmgen.inactive_image_namespace.v1',
            completeness => 'structure_only; contents_and_reference_semantics_unqualified',
            lock => $lock,
            %$census};
        1;
    };
    my $error = $@;
    # Closing the owning descriptor releases cooperation on every success and
    # failure path. The permanent named lock is intentionally left in place.
    my $closed = close($handle);
    die $error unless $ok;
    die "cannot close permanent lock: $!\n" unless $closed;
    return $result;
}
